-- Only the isolated synthetic fixture. Roll back all rows and notifications.
begin;
create or replace function pg_temp.require(ok boolean,label text) returns void language plpgsql as $$begin if ok is distinct from true then raise exception 'Prompt38 assertion failed: %',label;end if;end$$;
do $$
declare leader uuid:=gen_random_uuid();member uuid:=gen_random_uuid();reviewer uuid:=gen_random_uuid();outsider uuid:=gen_random_uuid();p uuid:=gen_random_uuid();t uuid:=gen_random_uuid();other_task uuid:=gen_random_uuid();period uuid;doing uuid;review uuid;stage uuid;b jsonb;batch uuid;client uuid:=gen_random_uuid();second_client uuid:=gen_random_uuid();reference_client uuid:=gen_random_uuid();doc uuid;files jsonb;data jsonb;failed boolean;i integer;v integer;
begin
 insert into profiles(id,full_name)values(leader,'Documentation Leader'),(member,'Assigned Member'),(reviewer,'Authorized Reviewer'),(outsider,'Outside User');
 insert into projects(id,owner_id,title,slug,status,visibility)values(p,leader,'Documentation synthetic','p38-'||p,'in_progress','private');
 insert into project_members(project_id,user_id,status,role)values(p,member,'active','member'),(p,reviewer,'active','member');
 insert into project_recruitment_roles(project_id,user_id,level)values(p,reviewer,'reviewer');
 insert into project_workspace_modules(project_id,module)values(p,'reports')on conflict(project_id,module)do nothing;
 select id into period from activity_periods where project_id=p and is_active;
 if period is null then insert into activity_periods(project_id,name,is_active,created_by)values(p,'2026.2',true,leader)returning id into period;end if;
 select id into doing from activity_stages where project_id=p and kind='doing' limit 1;
 select id into review from activity_stages where project_id=p and kind='review' limit 1;
 insert into activity_tasks(id,project_id,period_id,title,description,stage_id,assignees,reviewer_id,requires_review)values(t,p,period,'Evidence review','Registered description only',doing,array[member],reviewer,true),(other_task,p,period,'Another task','',doing,array[member],reviewer,false);
 select jsonb_agg(jsonb_build_object('name','file'||n||'.txt','size',10,'mime','text/plain','sha256',repeat('a',64)))into files from generate_series(1,5)n;
 b:=documentation_private.begin_upload(member,'activity',t,client,'',null,files,'{}',false);batch:=(b->>'id')::uuid;
 for i in 0..4 loop insert into storage.objects(bucket_id,name,metadata)values('activity-evidence',member||'/'||batch||'/'||i,'{"size":10,"mimetype":"text/plain"}');end loop;
 perform documentation_private.complete_upload(member,client);
 set constraints all immediate;set constraints all deferred;
 perform pg_temp.require((select count(*)=5 from activity_comment_attachments where comment_id=client),'five attachments on one comment');
 perform pg_temp.require((select body='' from activity_comments where id=client),'attachment-only message');
 perform documentation_private.complete_upload(member,client);
 perform pg_temp.require((select count(*)=1 from activity_comments where id=client),'upload retry is idempotent');
 b:=documentation_private.begin_upload(member,'activity',t,second_client,'Second message',client,files,'{}',false);batch:=(b->>'id')::uuid;
 for i in 0..4 loop insert into storage.objects(bucket_id,name,metadata)values('activity-evidence',member||'/'||batch||'/'||i,'{"size":10,"mimetype":"text/plain"}');end loop;
 perform documentation_private.complete_upload(member,second_client);
 perform pg_temp.require((select count(*)=10 from activity_comment_attachments where task_id=t),'limit is per message, not per task');
 failed:=false;begin perform documentation_private.begin_upload(member,'activity',t,gen_random_uuid(),'Six',null,files||jsonb_build_array(files->0),'{}',false);exception when raise_exception then failed:=true;end;perform pg_temp.require(failed,'sixth attachment rejected');
 failed:=false;begin perform documentation_private.begin_upload(member,'activity',t,gen_random_uuid(),'Big',null,jsonb_build_array(jsonb_build_object('name','big.txt','size',10485761,'mime','text/plain','sha256',repeat('a',64))),'{}',false);exception when raise_exception then failed:=true;end;perform pg_temp.require(failed,'10 MB server limit');
 failed:=false;begin perform documentation_private.begin_upload(outsider,'activity',t,gen_random_uuid(),'Outside',null,files,'{}',false);exception when raise_exception then failed:=true;end;perform pg_temp.require(failed,'cross-project upload denied');
 perform set_config('request.jwt.claim.sub',member::text,true);execute 'set local role authenticated';
 perform public.send_activity_discussion(t,'Text-only reply',gen_random_uuid(),client,false);
 failed:=false;begin perform public.send_activity_discussion(other_task,'Cross task reply',gen_random_uuid(),client,false);exception when raise_exception then failed:=true;end;perform pg_temp.require(failed,'cross-task reply denied');
 data:=public.get_activity_dialog(t,p,null);perform pg_temp.require(jsonb_array_length(data->'details'->'comments')=3,'comments and replies retained');
 perform pg_temp.require(data::text like '%file1.txt%','attachments visible in existing dialog RPC');
 data:=public.get_documentation_data('p38-'||p,null);perform pg_temp.require(data->'project'->>'title'='Documentation synthetic' and jsonb_array_length(data->'tasks')=2,'authorized facts collected');
 perform pg_temp.require(data::text not like '%Text-only reply%' and data::text not like '%sha256%' and data::text not like '%email%','private discussion and sensitive data excluded');
 failed:=false;begin perform public.begin_document_upload(member,'activity',t,gen_random_uuid(),'x',null,files,'{}',false);exception when insufficient_privilege then failed:=true;end;perform pg_temp.require(failed,'browser cannot manufacture validated upload manifest');
 perform set_config('request.jwt.claim.sub',outsider::text,true);
 perform pg_temp.require((select count(*)=0 from activity_comment_attachments where task_id=t),'attachment RLS blocks cross-project reads');
 failed:=false;begin perform public.get_documentation_data('p38-'||p,null);exception when raise_exception then failed:=true;end;perform pg_temp.require(failed,'cross-project export denied');execute 'reset role';
 b:=documentation_private.begin_upload(leader,'reference',null,reference_client,'',null,jsonb_build_array(jsonb_build_object('name','guide.pdf','size',10,'mime','application/pdf','sha256',repeat('a',64))),'{"name":"Synthetic institutional guide","distribution_authorized":true}',false);batch:=(b->>'id')::uuid;
 insert into storage.objects(bucket_id,name,metadata)values('academic-references',leader||'/'||batch||'/0','{"size":10,"mimetype":"application/pdf"}');doc:=documentation_private.complete_upload(leader,reference_client);
 execute 'set local role authenticated';perform set_config('request.jwt.claim.sub',leader::text,true);perform pg_temp.require((select status='pending' from reference_documents where id=doc),'owner sees pending upload');
 failed:=false;begin update reference_documents set status='published' where id=doc;exception when insufficient_privilege then failed:=true;end;perform pg_temp.require(failed,'owner cannot self-publish');
 failed:=false;begin perform review_reference_document(doc,'published','');exception when insufficient_privilege then failed:=true;end;perform pg_temp.require(failed,'project leader has no global moderation privilege');
 perform set_config('request.jwt.claim.sub',outsider::text,true);perform pg_temp.require((select count(*)=0 from reference_documents where id=doc),'unpublished references private');execute 'reset role';
 perform documentation_private.review_reference(doc,'published','Manual content and distribution review');execute 'set local role authenticated';perform pg_temp.require((select count(*)=1 from reference_documents where id=doc),'published references shared globally');execute 'reset role';
 -- Existing review mutation remains the authority: no bypass, mandatory return reason, and repeatable review.
 perform set_config('request.jwt.claim.sub',member::text,true);select version into v from activity_tasks where id=t;perform mutate_activity(p,'move',jsonb_build_object('id',t,'version',v,'stage_id',review));
 select version into v from activity_tasks where id=t;failed:=false;begin perform mutate_activity(p,'approve',jsonb_build_object('id',t,'version',v));exception when raise_exception then failed:=true;end;perform pg_temp.require(failed,'assignee cannot approve own mandatory review');
 perform set_config('request.jwt.claim.sub',reviewer::text,true);failed:=false;begin perform mutate_activity(p,'return',jsonb_build_object('id',t,'version',v,'reason',''));exception when raise_exception then failed:=true;end;perform pg_temp.require(failed,'return requires justification');
 perform mutate_activity(p,'return',jsonb_build_object('id',t,'version',v,'reason','Correct the evidence'));perform set_config('request.jwt.claim.sub',member::text,true);select version into v from activity_tasks where id=t;perform mutate_activity(p,'move',jsonb_build_object('id',t,'version',v,'stage_id',review));
 perform set_config('request.jwt.claim.sub',reviewer::text,true);select version into v from activity_tasks where id=t;perform mutate_activity(p,'approve',jsonb_build_object('id',t,'version',v));
 perform pg_temp.require((select count(*)=4 from activity_history where task_id=t and action in ('move','return','approve')),'review decisions and resubmission preserved');
 perform pg_temp.require((select count(*)=10 from activity_comment_attachments where task_id=t),'review never deletes evidence');
 perform set_config('request.jwt.claim.sub',leader::text,true);update projects set status='completed' where id=p;
 failed:=false;begin perform documentation_private.begin_upload(member,'activity',t,gen_random_uuid(),'Closed',null,files,'{}',false);exception when raise_exception then failed:=true;end;perform pg_temp.require(failed,'historical project rejects new attachments');
 perform set_config('request.jwt.claim.sub',member::text,true);perform pg_temp.require((public.get_activity_dialog(t,p,null)->>'projectReadOnly')::boolean,'historical discussion readable');
 perform pg_temp.require(public.get_documentation_data('p38-'||p,null)->'project'->>'status'='completed','historical facts export preserved');
end$$;
rollback;
